from fractions import Fraction as F
def stage(D,mlo=0.2,mhi=0.3,zpmin=12,zmax=76):
    d={}
    for zp in range(zpmin,40):
        for zw in range(zpmin,zmax):
            m=2*D/(zp+zw)
            if mlo<=m<=mhi: d.setdefault(F(zw,zp),[]).append((zp,zw,round(m,4)))
    return d
def first(D1,D2,rM,mlo=0.2,mhi=0.3,zpmin=12,zmax=76):
    out=[]
    for a in range(zpmin,zmax):
        mp=a/rM
        if mp.denominator!=1 or mp<zpmin or mp>zmax: continue
        m=2*D1/(a+mp)
        if not(mlo<=m<=mhi): continue
        xp=2*D2/m-a
        if abs(xp-round(xp))>1e-6 or round(xp)<zpmin: continue
        out.append((a,int(mp),round(xp),round(m,4)))
    return out
grid=lambda a,b:[round(x*0.1,1) for x in range(int(a*10),int(b*10)+1)]
st={D:stage(D) for D in grid(5.0,8.5)}
res=[]
for D1 in grid(6.0,8.0):
  for D2 in grid(4.8,6.5):
    fb=first(D1,D2,F(1)); fv=first(D1,D2,F(3,4))
    if not fb or not fv: continue
    for D3 in grid(6.0,8.0):
      for D4 in grid(5.0,7.5):
        def solve(f,T):
            for (a,mp,xp,m) in f:
                rest=T/F(a,xp)
                for r2,l2 in st[D3].items():
                    r3=rest/r2
                    if r3 in st[D4]:
                        return (a,mp,xp,m,l2[0],st[D4][r3][0])
            return None
        sb=solve(fb,F(60)); 
        if not sb: continue
        sv=solve(fv,F(45))
        if sv: res.append((D1,D2,D3,D4,sb,sv))
print(len(res))
for r in res[:25]: print(r)
