        com=((a+b+c)/4*vol[:,None]).sum(0)/vol.sum()
        cd=np.hypot(com[0]-ax[0],com[1]-ax[1])
        proj=p.project(); area=proj.area(); frac=area/(math.pi*reach**2)
        print(tag,hn,'reach %.2f lowz %.2f (frame top %.2f) com %.2f cover %.3f'%(reach,low,fixedtop,cd,frac))
    d=np.hypot(*(np.array(M.axis[hs['day']['mobile']])-np.array(M.axis[hs['hour']['mobile']]))); print(tag,'day-hour axis dist',d)
    # case fit
    C=np.array(j['case_centre']); worst=0
